from pathlib import Path
p=Path('作业二/提交_这一次轮椅该听谁的/交互原型v1/app.js')
s=p.read_text(encoding='utf-8')
s=s.replace("reviewDone:false};", "reviewDone:false,following:false};",1)
s=s.replace('B2 底盘尚无此门口的通行记录', '${state.body} 底盘本次通行条件仍需确认')
s=s.replace("${choice(a?'等维修方现场复核':'请现场工作人员协助',a?'等待与通过共 19 分钟；迟到 13 分钟。':'先确认求助内容；等待与通过共 9 分钟，迟到 3 分钟。',a?'wait':'help')}", "${choice('请现场工作人员协助','先确认求助内容；等待与通过共 9 分钟，迟到 3 分钟。','help')}${choice('等维修方现场复核','等待与通过共 19 分钟；迟到 13 分钟。','wait')}")
s=s.replace("<div class=\"two-col\"><div><blockquote>${a?", "<div class=\"two-col\"><div>${state.following&&state.saved?`<div class=\"rule-note\">按你的反馈：${D.feedback[state.saved.pref].label}</div>`:''}<blockquote>${state.following&&state.saved&&state.rule==='B'?D.feedback[state.saved.pref].reply:a?")
s=s.replace("['A：等待维修复核'", "['A / B：等待维修复核'")
s=s.replace("['B：直接请求协助'", "['A / B：直接请求协助'")
s=s.replace("case'next-choice':state.rule='B';state.reviewDone=false;go('choice');", "case'next-choice':state.rule='B';state.reviewDone=false;state.following=true;go('choice');")
s=s.replace("case'begin':case'story-start':state.reviewDone=false;", "case'begin':case'story-start':state.reviewDone=false;state.following=false;")
s=s.replace("notice:'',reviewDone:false});", "notice:'',reviewDone:false,following:false});")
s=s.replace('按本人选择调整选项顺序或说明长度。','按本人选择调整开口方式或说明长度。')
s=s.replace("app.innerHTML=html;if(focus)", "app.innerHTML=html;if(state.step==='choice'&&state.following&&state.saved?.pref==='detour'&&state.rule==='B'){const list=app.querySelector('.choice-list');list?.prepend(list.querySelector('[data-action=\"detour\"]'));}if(focus)")
p.write_text(s,encoding='utf-8')
